// GENERATED by port-tests.py from ../xb-chat/test: the Node tests, run against the Rust server.
// Phone-number accounts and multi-device, the WhatsApp way: SMS code login,
// staying logged in with the device key, QR linking, every device getting
// every message (including what I sent from my other devices), read sync,
// and moving the number to a new phone.

import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { after, before, describe, test } from 'node:test';
import { startRust } from './rust.js';
import { Client } from '../../xb-chat/clients/node/client.js';
import { MemoryKeyStore } from '../../xb-chat/clients/node/signal-node.js';
import { generateKeyPair } from '../../xb-chat/protocol/noise.js';

let dir, chat, phoneAuth;
// A stand-in for FCM: records wake-ups; tokens starting "dead" are rejected.
const pushes = [];
const fakePush = { send: async (token, data) => (pushes.push({ token, data }), token.startsWith('dead') ? { ok: false, invalid: true } : { ok: true }) };
const open = [];

before(async () => {
  dir = await fs.mkdtemp(path.join(os.tmpdir(), 'xb-md-'));
  chat = await startRust({ dir, env: { XB_FAKE_PUSH: '1', XB_LINK_TTL_MS: '300', XB_PUSH_COOLDOWN_MS: '300', XB_CODE_RESEND_MS: '200' } });
});

after(async () => {
  for (const c of open) c.close();
  await chat.close();
  await fs.rm(dir, { recursive: true, force: true });
});

const next = (em, ev, filter = () => true, ms = 4000) =>
  new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`timed out waiting for ${ev}`)), ms);
    const on = (...v) => {
      if (!filter(...v)) return;
      clearTimeout(timer);
      em.off(ev, on);
      resolve(v.length > 1 ? v : v[0]);
    };
    em.on(ev, on);
  });
const tick = (ms = 60) => new Promise((r) => setTimeout(r, ms));

// A device: its Noise key (login) and its end-to-end keys, like a phone's storage.
const newDevice = () => ({ staticKeyPair: generateKeyPair(), keyStore: new MemoryKeyStore() });

async function client(dev) {
  const c = new Client({ port: chat.port, serverPublicKey: chat.publicKey, ...dev });
  c.on('error', () => {});
  open.push(c);
  await c.connect();
  return c;
}

// Registers `phone` on a new device (SMS code flow) and returns it, logged in.
async function register(phone, name, dev = newDevice()) {
  const c = await client(dev);
  const { dev: code, length } = await c.requestCode(phone);
  assert.equal(length, 6);
  const res = await c.verifyCode(phone, code, { name, device: 'Pixel', platform: 'android' });
  assert.equal(res.jid, `${phone}@s.xb`);
  assert.equal(res.device, 0, 'the verified phone is the primary device');
  return { c, dev };
}

// Links a companion to `primary` through the QR flow.
async function link(primary, dev = newDevice(), name = 'Chrome') {
  const web = await client(dev);
  const qr = next(web, 'qr');
  const loggedIn = web.link({ name, platform: 'web' });
  const [code] = await qr;
  assert.match(code, /^xb1,[\w-]+,[\w+/=]+$/);
  const approved = await primary.approveLink(code);
  const res = await loggedIn;
  assert.equal(res.device, approved.no);
  return { c: web, dev };
}

const ASHA = '919800000001';
const RAVI = '919800000002';

describe('push wake-ups', () => {
  test('a message for a disconnected phone wakes it (no content); connected phones are not pushed', async () => {
    const { c: asha, dev } = await register('919800000601', 'Asha');
    const { c: ravi } = await register('919800000602', 'Ravi');
    const token = 'fcm-token-for-ashas-phone-0123456789';
    await asha.setPushToken(token);

    // Online: delivered over the connection, no push.
    const got = next(asha, 'message');
    await ravi.sendEncrypted('919800000601@s.xb', [{ tag: 'body', attrs: {}, content: Buffer.from('hi') }]);
    await got;
    await tick();
    assert.equal((await chat.store.pushes()).length, 0);

    // Asha's app goes to the background and disconnects: the next message wakes her phone.
    asha.close();
    await tick();
    await ravi.sendEncrypted('919800000601@s.xb', [{ tag: 'body', attrs: {}, content: Buffer.from('are you there?') }]);
    await ravi.sendEncrypted('919800000601@s.xb', [{ tag: 'body', attrs: {}, content: Buffer.from('second, same burst') }]);
    await tick();
    assert.equal((await chat.store.pushes()).length, 1, 'one wake-up per burst');
    assert.equal((await chat.store.pushes())[0].token, token);
    assert.deepEqual((await chat.store.pushes())[0].data, { xb: 'wake' }, 'nothing about the message itself');

    // Woken: it connects and gets both messages from its queue.
    const back = await client(dev);
    const texts = [];
    back.on('message', (m) => texts.push(m.text));
    await back.loginDevice('919800000601');
    for (let i = 0; i < 40 && texts.length < 2; i++) await tick(50);
    assert.deepEqual(texts, ['are you there?', 'second, same burst']);

    // A token Google no longer accepts is forgotten.
    await back.setPushToken('dead-token-uninstalled-app-0123456789');
    back.close();
    await tick();
    await ravi.sendEncrypted('919800000601@s.xb', [{ tag: 'body', attrs: {}, content: Buffer.from('x') }]);
    await tick();
    assert.equal((await chat.store.pushes()).at(-1).token.startsWith('dead'), true);
    assert.equal(await chat.store.pushOf('919800000601', (await chat.store.devices('919800000601'))[0].e2e), null);
    ravi.close();
  });
});

describe('privacy', () => {
  test('photo, about, last seen / online and read receipts follow the owner\'s settings', async () => {
    const { c: asha } = await register('919800000701', 'Asha');
    const { c: ravi } = await register('919800000702', 'Ravi');
    const jpeg = (n) => Buffer.concat([Buffer.from([0xff, 0xd8, 0xff, 0xe0]), randomBytes(n)]);
    await asha.setPicture(jpeg(2000), jpeg(300));
    await asha.setAbout('Busy');
    asha.setAvailable(true);
    await tick();

    // Defaults: everyone sees everything.
    assert.deepEqual(await asha.getPrivacy(), { last: 'all', online: 'all', photo: 'all', about: 'all', receipts: true });
    let [u] = await ravi.lookup(['919800000701']);
    assert.ok(u.picture && u.about === 'Busy');
    assert.equal((await ravi.lastSeen('919800000701')).online, true);

    // Photo: my contacts; about and last seen: nobody; online: same as last seen.
    await asha.setPrivacy({ photo: 'contacts', about: 'none', last: 'none', online: 'match' });
    [u] = await ravi.lookup(['919800000701']);
    assert.equal(u.picture, undefined);
    assert.equal(u.about, undefined);
    assert.equal(await ravi.getPicture('919800000701'), null);
    const seen = await ravi.lastSeen('919800000701');
    assert.equal(seen.online, false, 'online hidden like last seen');
    assert.equal(seen.t, undefined);

    // Ravi becomes one of Asha's contacts: the photo shows; about stays hidden.
    assert.equal(await asha.setContacts(['919800000702', '919899999999']), 1, 'only registered numbers are kept');
    [u] = await ravi.lookup(['919800000701']);
    assert.ok(u.picture);
    assert.equal(u.about, undefined);

    // Who hides their last seen can't see other people's (WhatsApp's rule).
    ravi.setAvailable(false);
    await tick();
    assert.ok((await asha.lastSeen('919800000702')).t === undefined);

    // Read receipts off (Asha): Ravi's message gets delivered, never read.
    await asha.setPrivacy({ receipts: false });
    const receipts = [];
    ravi.on('receipt', (r) => receipts.push(r.type));
    const got = next(asha, 'message');
    await ravi.sendEncrypted('919800000701@s.xb', [{ tag: 'body', attrs: {}, content: Buffer.from('hi') }]);
    asha.markRead(await got);
    await tick(300);
    assert.deepEqual(receipts, ['delivered']);

    // Back on: blue ticks again.
    await asha.setPrivacy({ receipts: true });
    const got2 = next(asha, 'message');
    await ravi.sendEncrypted('919800000701@s.xb', [{ tag: 'body', attrs: {}, content: Buffer.from('again') }]);
    const read = next(ravi, 'receipt', (r) => r.type === 'read');
    asha.markRead(await got2);
    await read;

    await assert.rejects(asha.setPrivacy({ last: 'friends' }), { code: 'bad-request' });
    asha.close();
    ravi.close();
  });
});

describe('profile: photo and about', () => {
  test('set, look up, download, live update, remove', async () => {
    const { c: asha } = await register('919800000501', 'Asha');
    const { c: ravi } = await register('919800000502', 'Ravi');
    const jpeg = (n) => Buffer.concat([Buffer.from([0xff, 0xd8, 0xff, 0xe0]), randomBytes(n)]);
    const image = jpeg(40_000);
    const preview = jpeg(3_000);

    // Ravi has Asha's chat open (watches her presence): he hears about changes.
    ravi.subscribePresence('919800000501');
    await tick();
    const heard = next(ravi, 'notification', (n) => n.picture);
    const id = await asha.setPicture(image, preview);
    assert.match(id, /^[0-9a-f]{16}$/);
    const note = await heard;
    assert.equal(note.type, 'profile');
    assert.equal(note.from, '919800000501@s.xb');
    assert.equal(note.picture, id);

    const aboutNote = next(ravi, 'notification', (n) => n.about !== undefined);
    await asha.setAbout('At work 🏢');
    assert.equal((await aboutNote).about, 'At work 🏢');

    const [u] = await ravi.lookup(['919800000501']);
    assert.deepEqual([u.name, u.about, u.picture], ['Asha', 'At work 🏢', id]);
    const small = await ravi.getPicture('919800000501');
    assert.equal(small.id, id);
    assert.ok(small.bytes.equals(preview));
    assert.ok((await ravi.getPicture('919800000501', 'image')).bytes.equals(image));

    // Contact discovery: a whole address book in one go is fine, more than 1000 numbers is not.
    const book = Array.from({ length: 1000 }, (_, i) => `9198${String(i).padStart(8, '0')}`);
    assert.equal((await ravi.lookup(book)).length, 1000);
    await assert.rejects(ravi.lookup([...book, '919800000501']), { code: 'bad-request' });

    // Not a JPEG, too long an about: refused.
    await assert.rejects(asha.setPicture(Buffer.from('<svg/>'), preview), { code: 'bad-request' });
    await assert.rejects(asha.setAbout('x'.repeat(140)), { code: 'bad-request' });

    // Removed: gone for everyone.
    const removed = next(ravi, 'notification', (n) => n.picture === '');
    assert.equal(await asha.setPicture(null), null);
    await removed;
    assert.equal(await ravi.getPicture('919800000501'), null);
    assert.equal((await ravi.lookup(['919800000501']))[0].picture, undefined);
    asha.close();
    ravi.close();
  });
});

describe('phone number login', () => {
  test('wrong codes fail, resends are rate limited, the right code logs in', async () => {
    const c = await client(newDevice());
    await assert.rejects(c.requestCode('12345'), { code: 'invalid-phone' });
    const { dev: code } = await c.requestCode('919800000099');
    await assert.rejects(c.requestCode('919800000099'), (err) => err.code === 'rate-limit' && err.retry >= 0);
    const wrong = code === '000000' ? '111111' : '000000';
    await assert.rejects(c.verifyCode('919800000099', wrong), { code: 'wrong-code' });
    const res = await c.verifyCode('919800000099', code, { name: 'Test' });
    assert.equal(res.name, 'Test');
    c.close();
  });

  test('the phone stays logged in with its device key, no code needed', async () => {
    const { c, dev } = await register(ASHA, 'Asha');
    c.close();
    const again = await client(dev);
    const res = await again.loginDevice(ASHA);
    assert.equal(res.device, 0);
    again.close();
    const stranger = await client(newDevice());
    await assert.rejects(stranger.loginDevice(ASHA), { code: 'not-authorized' });
    stranger.close();
  });

  test('the same device connecting twice: the old connection is told "conflict" (so it must not reconnect)', async () => {
    const dev = newDevice();
    const first = await client(dev);
    const { dev: code } = await first.requestCode('919800000033');
    await first.verifyCode('919800000033', code, { name: 'Twin' });
    const closed = new Promise((r) => first.once('close', r));
    const second = await client(dev);
    await second.loginDevice('919800000033');
    assert.equal(await closed, 'conflict', 'the older connection learns why it was closed');
    await tick();
    assert.ok(second.transport && !second.transport.closed, 'the newest connection stays');
    second.close();
  });
});

describe('linked devices', () => {
  let asha, ashaWeb, ravi, ashaDev, ashaWebDev, newPhone;

  before(async () => {
    const a = await register(ASHA, 'Asha');
    asha = a.c;
    ashaDev = a.dev;
    ravi = (await register(RAVI, 'Ravi')).c;
  });

  test('QR linking: rotating codes, only the primary can approve, a used code is gone', async () => {
    const w = await client(newDevice());
    const codes = [];
    w.on('qr', (q) => codes.push(q));
    const loggedIn = w.link({ name: 'Firefox' });
    await tick(700); // linkTtlMs is 300 ms in this test
    assert.ok(codes.length >= 2, 'a new QR code every ttl');
    assert.notEqual(codes[0].split(',')[1], codes.at(-1).split(',')[1]);
    await assert.rejects(asha.approveLink(codes[0]), { code: 'item-not-found' }); // expired
    const forged = codes.at(-1).replace(/,[^,]+$/, `,${generateKeyPair().public.toString('base64')}`);
    await assert.rejects(asha.approveLink(forged), { code: 'item-not-found' }); // another key
    await asha.approveLink(codes.at(-1));
    const res = await loggedIn;
    assert.equal(res.jid, `${ASHA}@s.xb`);
    assert.ok(res.device >= 1);
    // A companion can't link more devices.
    const x = await client(newDevice());
    const qr = next(x, 'qr');
    x.link().catch(() => {});
    await assert.rejects(w.approveLink(await qr), { code: 'forbidden' });
    x.close();
    // Unlink it again (the primary can).
    const d = (await asha.listDevices()).find((v) => v.name === 'Firefox');
    await asha.unlinkDevice(d.key);
    await tick();
    assert.equal((await asha.listDevices()).some((v) => v.name === 'Firefox'), false);
  });

  test('every device gets every message, and sees what I sent from my other devices', async () => {
    const l = await link(asha);
    ashaWeb = l.c;
    ashaWebDev = l.dev;
    await tick();

    // Ravi -> Asha: both of Asha's devices get it.
    const onPhone = next(asha, 'message');
    const onWeb = next(ashaWeb, 'message');
    await ravi.sendMessage(ASHA, 'hello Asha');
    for (const m of [await onPhone, await onWeb]) {
      assert.equal(m.text, 'hello Asha');
      assert.equal(m.fromMe, false);
      assert.equal(m.chat, `${RAVI}@s.xb`);
      assert.equal(m.notify, 'Ravi');
    }

    // Asha replies from the web: Ravi gets it, and so does Asha's phone, as sent by her.
    const atRavi = next(ravi, 'message');
    const syncOnPhone = next(asha, 'message');
    await ashaWeb.sendMessage(RAVI, 'hi Ravi, from the web');
    assert.equal((await atRavi).text, 'hi Ravi, from the web');
    const sync = await syncOnPhone;
    assert.equal(sync.fromMe, true);
    assert.equal(sync.chat, `${RAVI}@s.xb`);
    assert.equal(sync.text, 'hi Ravi, from the web');

    // Ravi's read receipt reaches both of Asha's devices.
    const r1 = next(asha, 'receipt', (r) => r.type === 'read' && r.id === sync.id);
    const r2 = next(ashaWeb, 'receipt', (r) => r.type === 'read' && r.id === sync.id);
    ravi.markRead({ id: sync.id, from: `${ASHA}@s.xb` });
    await Promise.all([r1, r2]);
  });

  test('reading on one device marks it read on the others', async () => {
    const onPhone = next(asha, 'message');
    const onWeb = next(ashaWeb, 'message');
    await ravi.sendMessage(ASHA, 'read me');
    const m = await onPhone;
    await onWeb;
    const readSelf = next(ashaWeb, 'receipt', (r) => r.type === 'read-self' && r.id === m.id);
    const readAtRavi = next(ravi, 'receipt', (r) => r.type === 'read' && r.id === m.id);
    asha.markRead(m);
    assert.equal((await readSelf).from, `${RAVI}@s.xb`);
    await readAtRavi;
  });

  test('an offline companion gets its own copy when it comes back', async () => {
    ashaWeb.close();
    await tick();
    const onPhone = next(asha, 'message');
    await ravi.sendMessage(ASHA, 'while the web was closed');
    await onPhone;
    await tick();
    assert.equal(await chat.store.pendingCount(ASHA) >= 1, true, 'still queued for the web');

    const back = await client(ashaWebDev);
    const got = next(back, 'message', (m) => m.text === 'while the web was closed');
    await back.loginDevice(ASHA);
    await got;
    ashaWeb = back;
  });

  test('groups: members and my other devices each get their copy', async () => {
    const g = await ravi.createGroup('Family', [ASHA]);
    const onPhone = next(asha, 'message');
    const onWeb = next(ashaWeb, 'message');
    await ravi.sendGroupMessage(g.id, 'dinner at 8');
    for (const m of [await onPhone, await onWeb]) {
      assert.equal(m.text, 'dinner at 8');
      assert.equal(m.chat, g.jid);
    }
    const atRavi = next(ravi, 'message');
    const syncOnWeb = next(ashaWeb, 'message');
    await asha.sendGroupMessage(g.id, 'coming');
    assert.equal((await atRavi).participant, `${ASHA}@s.xb`);
    const s = await syncOnWeb;
    assert.equal(s.fromMe, true);
    assert.equal(s.chat, g.jid);
  });

  test('device-to-device protocol messages (history sync) reach only my devices', async () => {
    const got = next(ashaWeb, 'protocol');
    let raviGot = false;
    ravi.on('protocol', () => (raviGot = true));
    await asha.sendEncrypted(ASHA, [{ tag: 'protocol', attrs: { type: 'history', for: '42' }, content: Buffer.from('{"chats":[]}') }]);
    const p = await got;
    assert.equal(p.type, 'history');
    assert.equal(p.for, '42');
    assert.equal(Buffer.from(p.content).toString(), '{"chats":[]}');
    await tick();
    assert.equal(raviGot, false);
  });

  test('moving the number to a new phone logs out every other device', async () => {
    const ended = [next(asha, 'stream_end'), next(ashaWeb, 'stream_end')];
    newPhone = (await register(ASHA, 'Asha')).c;
    assert.deepEqual(await Promise.all(ended), ['device-removed', 'device-removed']);
    const devices = await newPhone.listDevices();
    assert.equal(devices.length, 1);
    assert.equal(devices[0].no, 0);
    // The old phone's key no longer logs in.
    const old = await client(ashaDev);
    await assert.rejects(old.loginDevice(ASHA), { code: 'not-authorized' });
    old.close();
    // And Ravi can still write to Asha (his device list is refreshed).
    const got = next(newPhone, 'message');
    await ravi.sendMessage(ASHA, 'welcome back');
    assert.equal((await got).text, 'welcome back');
  });

  test('profile: names and who is on xb-chat', async () => {
    await ravi.setName('Ravi K');
    const res = await newPhone.lookup([RAVI, '919800000077']);
    assert.deepEqual(res.map((u) => [u.exists, u.name]), [[true, 'Ravi K'], [false, undefined]]);
  });
});
